import heapq


def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    k = len(prices)
    graph = [[] for _ in range(n)]
    for u, v, cost, zone in edges:
        graph[u].append((v, cost, zone))
        graph[v].append((u, cost, zone))
    avail = [[] for _ in range(n)]
    seen = [set() for _ in range(n)]
    for stop, z in stations:
        if 0 <= stop < n and 0 <= z < k and z not in seen[stop]:
            seen[stop].add(z)
            avail[stop].append(z)
    masks = 1 << k
    inf = 10**18
    dist = [[inf] * masks for _ in range(n)]
    dist[0][0] = 0
    heap = [(0, 0, 0)]
    while heap:
        d, u, mask = heapq.heappop(heap)
        if d != dist[u][mask]:
            continue
        if u == n - 1:
            return d
        for z in avail[u]:
            bit = 1 << z
            if mask & bit:
                continue
            nmask = mask | bit
            nd = d + prices[z]
            if nd < dist[u][nmask]:
                dist[u][nmask] = nd
                heapq.heappush(heap, (nd, u, nmask))
        for v, cost, zone in graph[u]:
            if 0 <= zone < k and (mask & (1 << zone)):
                pay = 0
            else:
                pay = cost
            nd = d + pay
            if nd < dist[v][mask]:
                dist[v][mask] = nd
                heapq.heappush(heap, (nd, v, mask))
    return -1
